function states.parse_u0_ipv4_ihl(buf, pinfo, tree, off, depth)
  depth = depth + 1
  if depth > 13 then
    tree:add_proto_expert_info(ef_error, "max depth exceeded")
    return off
  end
  local avail = buf:len() * 8
  if v.v_u0_ipv4_ihl == 0 then
    tree:add_proto_expert_info(ef_error, "InvalidIPv4Header")
    return off
  elseif v.v_u0_ipv4_ihl == 1 then
    tree:add_proto_expert_info(ef_error, "InvalidIPv4Header")
    return off
  elseif v.v_u0_ipv4_ihl == 2 then
    tree:add_proto_expert_info(ef_error, "InvalidIPv4Header")
    return off
  elseif v.v_u0_ipv4_ihl == 3 then
    tree:add_proto_expert_info(ef_error, "InvalidIPv4Header")
    return off
  elseif v.v_u0_ipv4_ihl == 4 then
    tree:add_proto_expert_info(ef_error, "InvalidIPv4Header")
    return off
  elseif v.v_u0_ipv4_ihl == 5 then
    return states.dispatch_on_u0_protocol(buf, pinfo, tree, off, depth)
  else
    return states.parse_u0_ipv4options(buf, pinfo, tree, off, depth)
  end
end

function states.parse_u0_ipv4options(buf, pinfo, tree, off, depth)
  depth = depth + 1
  if depth > 13 then
    tree:add_proto_expert_info(ef_error, "max depth exceeded")
    return off
  end
  local avail = buf:len() * 8
  local hdr_u0_ipv4options = tree:add(pf.f_hdr_u0_ipv4options, buf(math.floor(off / 8)))
  local len_u0_ipv4options_options = (((v.v_u0_ipv4_ihl - 5) * 4) * 8)
  if len_u0_ipv4options_options < 0 or off + len_u0_ipv4options_options > avail then
    hdr_u0_ipv4options:add_proto_expert_info(ef_error, "out of bounds in u0_ipv4options.options")
    return off
  end
  if len_u0_ipv4options_options > 0 then
    hdr_u0_ipv4options:add(pf.f_u0_ipv4options_options, buf(math.floor(off / 8), math.floor(len_u0_ipv4options_options / 8)))
  end
  off = off + len_u0_ipv4options_options
  return states.dispatch_on_u0_protocol(buf, pinfo, tree, off, depth)
end

function states.dispatch_on_u0_protocol(buf, pinfo, tree, off, depth)
  depth = depth + 1
  if depth > 13 then
    tree:add_proto_expert_info(ef_error, "max depth exceeded")
