function states.parse_customer_ipv4_ihl(buf, pinfo, tree, off, depth)
  depth = depth + 1
  if depth > 13 then
    tree:add_proto_expert_info(ef_error, "max depth exceeded")
    return off
  end
  local avail = buf:len() * 8
  if v.v_customer_ipv4_ihl == 5 then
    return states.dispatch_on_customer_protocol(buf, pinfo, tree, off, depth)
  else
    tree:add_proto_expert_info(ef_error, "IPv4OptionsNotSupported")
    return off
  end
end

function states.dispatch_on_customer_protocol(buf, pinfo, tree, off, depth)
  depth = depth + 1
  if depth > 13 then
    tree:add_proto_expert_info(ef_error, "max depth exceeded")
    return off
  end
  local avail = buf:len() * 8
  if v.v_customer_ipv4_protocol == 17 then
    return states.parse_customer_udp(buf, pinfo, tree, off, depth)
  elseif v.v_customer_ipv4_protocol == 6 then
    return states.parse_customer_tcp(buf, pinfo, tree, off, depth)
  else
    add_payload(buf, tree, off)
    return off
  end
end

